Roundtrip with ServerSentEventStream
```ts
import { ServerSentEventParseStream } from "@ende/http/server-sent-event-parse-stream";
import { ServerSentEventStream } from "@ende/http/server-sent-event-stream";
import { assertEquals } from "@ende/assert";

const original = [
  { data: "hello" },
  { event: "update", data: "world" },
  { id: "1", data: "with id" },
];

const encoded = ReadableStream.from(original)
  .pipeThrough(new ServerSentEventStream());

const decoded = encoded.pipeThrough(new ServerSentEventParseStream());
const result = await Array.fromAsync(decoded);

assertEquals(result, original);
```

