Response with Cache-Control and ETag
```ts ignore
import { formatCacheControl } from "@ende/http/unstable-cache-control";
import { eTag } from "@ende/http/etag";

Ende.serve(async (_req) => {
  const body = "hello";
  const etag = await eTag(body);
  const headers = new Headers();
  if (etag) headers.set("etag", etag);
  headers.set("cache-control", formatCacheControl({
    maxAge: 3600,
    private: true,
    mustRevalidate: true,
  }));
  return new Response(body, { headers });
});
```

Parse request Cache-Control
```ts ignore
import { parseCacheControl } from "@ende/http/unstable-cache-control";

Ende.serve((req) => {
  const cc = parseCacheControl(req.headers.get("cache-control"));
  if (cc.noStore) {
    return new Response(null, { status: 400 }); // client forbids storing
  }
  return new Response("OK");
});
```

